find_package(geometry_msgs REQUIRED)



add_executable(odom2path src/odom2path.cpp)

ament_target_dependencies(
  sim_laser
  "rclcpp"
  "nav_msgs"
  "geometry_msgs"
)

install(TARGETS odom2path
  DESTINATION lib/${PROJECT_NAME})
3.编译
终端中进入当前工作空间，编译功能包：
