#include 
#include "rclcpp/rclcpp.hpp"
#include "std_msgs/msg/string.hpp"
#include "geometry_msgs/msg/twist.hpp"

using std::placeholders::_1;
using namespace std;
using namespace std::chrono_literals;

class VoiceControl : public rclcpp::Node
{
public:
    VoiceControl() : Node("voice_control_node"),lin_vel(0.0),ang_vel(0.0)
    {
        RCLCPP_INFO(this->get_logger(), "语音控制节点创建！");
        // 订阅方：用于监听语音识别模块发布的消息
        sub_ = this->create_subscription("voicewords", 10, std::bind(&VoiceControl::callback, this, _1));
        // 发布方：用于发布需要被合成语音的文本
        pub_ = this->create_publisher("ttswords", 10);
        // 发布方：用于向机器人发布速度指令
        cmd_vel_pub_ = this->create_publisher("cmd_vel", 10);
        // 定时器
        timer_ = this->create_wall_timer(100ms,std::bind(&VoiceControl::cmd_vel_pub,this));
    }

private:
    rclcpp::TimerBase::SharedPtr timer_;
    double lin_vel, ang_vel;
    void cmd_vel_pub()
    {
        geometry_msgs::msg::Twist twist;
        twist.linear.x = lin_vel;
        twist.angular.z = ang_vel;
        cmd_vel_pub_->publish(twist);
    }
    void callback(const std_msgs::msg::String &msg)
    {
        // 处理订阅到的文本，并作出相应处理
        string dataString = msg.data;
        std_msgs::msg::String pubString;
        if (dataString.find("前进") != std::string::npos)
        {
            pubString.data = "开始前进";
            lin_vel = 0.3;
            ang_vel = 0.0;
        }
        else if (dataString.find("后退") != std::string::npos)
        {
            pubString.data = "开始后退";
            lin_vel = -0.3;
            ang_vel = 0.0;
        }
        else if (dataString.find("左转") != std::string::npos)
        {
            pubString.data = "开始左转";
            ang_vel = 0.5;
        }
        else if (dataString.find("右转") != std::string::npos)
        {
            pubString.data = "开始右转";
            ang_vel = -0.5;
        }
        else if (dataString.find("停止") != std::string::npos)
        {
            pubString.data = "停止";
            lin_vel = 0.0;
            ang_vel = 0.0;
        }
        else
        {
            pubString.data = msg.data;
        }
        cout publish(pubString);
    }
    rclcpp::Subscription::SharedPtr sub_;
    rclcpp::Publisher::SharedPtr pub_;
    rclcpp::Publisher::SharedPtr cmd_vel_pub_;
};

int main(int argc, char *argv[])
{
    rclcpp::init(argc, argv);
    rclcpp::spin(std::make_shared());
    rclcpp::shutdown();
    return 0;
}

